import{_ as s,o as n,c as t,a5 as e}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"41. 标准 I/O 和 printf/scanf","description":"The Little Book of C 中文版 — 41. 标准 I/O 和 printf/scanf","frontmatter":{"title":"41. 标准 I/O 和 printf/scanf","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","05-输入输出与文件","中文"],"description":"The Little Book of C 中文版 — 41. 标准 I/O 和 printf/scanf","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":41,"sidebarWeight":41,"alternateZh":"/posts/c教程/zh-CN/05-输入输出与文件/041-Standard IO and printfscanf","alternateEn":"/posts/c教程/en-US/05-Input Output and Files/041-Standard IO and printfscanf"},"headers":[],"relativePath":"posts/c教程/zh-CN/05-输入输出与文件/041-Standard IO and printfscanf.md","filePath":"posts/c教程/zh-CN/05-输入输出与文件/041-Standard IO and printfscanf.md","lastUpdated":1790163617000}'),p={name:"posts/c教程/zh-CN/05-输入输出与文件/041-Standard IO and printfscanf.md"};function i(o,a,d,l,c,r){return n(),t("div",null,[...a[0]||(a[0]=[e(`<p>[English version](/posts/c教程/en-US/05-Input Output and Files/041-Standard IO and printfscanf)</p><p>输入和输出是程序与外界对话的方式。在 C 中，几乎所有内容都通过标准 I/O 库，定义在<code>&lt;stdio.h&gt;</code>。你已经遇见过<code>printf()</code>在“Hello，C World”中，现在您将了解所有这些函数如何组合在一起、它们如何工作以及如何安全使用它们。</p><h4 id="标准流" tabindex="-1">标准流 <a class="header-anchor" href="#标准流" aria-label="Permalink to &quot;标准流&quot;">​</a></h4><p>每个 C 程序都会自动打开三个标准流：</p><table tabindex="0"><thead><tr><th>流</th><th>目的</th><th>示例函数</th></tr></thead><tbody><tr><td><code>stdin</code></td><td>标准输入（键盘或重定向文件）</td><td><code>scanf()</code>,<code>fgets()</code></td></tr><tr><td><code>stdout</code></td><td>标准输出（屏幕）</td><td><code>printf()</code>,<code>puts()</code></td></tr><tr><td><code>stderr</code></td><td>标准错误（屏幕，用于诊断）</td><td><code>fprintf(stderr, ...)</code></td></tr></tbody></table><p>您可以在终端中重定向这些流：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./program &lt; input.txt &gt; output.txt 2&gt; errors.log</span></span></code></pre></div><h4 id="使用-printf-打印" tabindex="-1">使用 printf() 打印 <a class="header-anchor" href="#使用-printf-打印" aria-label="Permalink to &quot;使用 printf() 打印&quot;">​</a></h4><p><code>printf()</code>格式化并打印数据到<code>stdout</code>。它的力量在于格式说明符，它描述了要打印的内容的类型和布局。</p><table tabindex="0"><thead><tr><th>类型</th><th>格式</th><th>示例</th></tr></thead><tbody><tr><td>整数</td><td><code>%d</code></td><td><code>printf(&quot;%d&quot;, 42);</code></td></tr><tr><td>浮动</td><td><code>%f</code></td><td><code>printf(&quot;%.2f&quot;, 3.1415);</code></td></tr><tr><td>字符</td><td><code>%c</code></td><td><code>printf(&quot;%c&quot;, &#39;A&#39;);</code></td></tr><tr><td>字符串</td><td><code>%s</code></td><td><code>printf(&quot;%s&quot;, &quot;Hello&quot;);</code></td></tr><tr><td>指针</td><td><code>%p</code></td><td><code>printf(&quot;%p&quot;, ptr);</code></td></tr><tr><td>十六进制</td><td><code>%x</code></td><td><code>printf(&quot;%x&quot;, 255);</code></td></tr></tbody></table><p>您可以控制宽度、精度和对齐方式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>printf(&quot;%-10s | %6.2f\\n&quot;, &quot;Price&quot;, 3.5);</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Price      |   3.50</span></span></code></pre></div><h4 id="小代码-打印所有内容" tabindex="-1">小代码：打印所有内容 <a class="header-anchor" href="#小代码-打印所有内容" aria-label="Permalink to &quot;小代码：打印所有内容&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int i = 42;</span></span>
<span class="line"><span>    float f = 3.1415;</span></span>
<span class="line"><span>    char c = &#39;C&#39;;</span></span>
<span class="line"><span>    char *s = &quot;Hello, C!&quot;;</span></span>
<span class="line"><span>    printf(&quot;Integer: %d\\n&quot;, i);</span></span>
<span class="line"><span>    printf(&quot;Float: %.2f\\n&quot;, f);</span></span>
<span class="line"><span>    printf(&quot;Char: %c\\n&quot;, c);</span></span>
<span class="line"><span>    printf(&quot;String: %s\\n&quot;, s);</span></span>
<span class="line"><span>    printf(&quot;Pointer: %p\\n&quot;, (void*)s);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Integer: 42</span></span>
<span class="line"><span>Float: 3.14</span></span>
<span class="line"><span>Char: C</span></span>
<span class="line"><span>String: Hello, C!</span></span>
<span class="line"><span>Pointer: 0x7ffeed001234</span></span></code></pre></div><h4 id="使用-scanf-读取" tabindex="-1">使用 scanf() 读取 <a class="header-anchor" href="#使用-scanf-读取" aria-label="Permalink to &quot;使用 scanf() 读取&quot;">​</a></h4><p><code>scanf()</code>读取格式化输入<code>stdin</code>。就像<code>printf()</code>相反，你告诉它格式，它会填充你的变量。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int age;</span></span>
<span class="line"><span>float height;</span></span>
<span class="line"><span>printf(&quot;Enter age and height: &quot;);</span></span>
<span class="line"><span>scanf(&quot;%d %f&quot;, &amp;age, &amp;height);</span></span>
<span class="line"><span>printf(&quot;You are %d years old and %.1f meters tall.\\n&quot;, age, height);</span></span></code></pre></div><p>输入：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>25 1.75</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>You are 25 years old and 1.8 meters tall.</span></span></code></pre></div><p>始终使用<code>&amp;</code>非数组变量的运算符 - 它传递应存储值的内存地址。</p><h4 id="更安全的输入-fgets-和-sscanf" tabindex="-1">更安全的输入：fgets() 和 sscanf() <a class="header-anchor" href="#更安全的输入-fgets-和-sscanf" aria-label="Permalink to &quot;更安全的输入：fgets() 和 sscanf()&quot;">​</a></h4><p><code>scanf()</code>对于字符串来说是有风险的，它不能防止缓冲区溢出。更安全的模式：使用<code>fgets()</code>读取整行，然后解析它。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>char buf[100];</span></span>
<span class="line"><span>printf(&quot;Enter your name: &quot;);</span></span>
<span class="line"><span>fgets(buf, sizeof(buf), stdin);</span></span>
<span class="line"><span>buf[strcspn(buf, &quot;\\n&quot;)] = &#39;\\0&#39;; // remove newline</span></span>
<span class="line"><span>printf(&quot;Hello, %s!\\n&quot;, buf);</span></span></code></pre></div><h4 id="结合-printf-和-scanf" tabindex="-1">结合 printf 和 scanf <a class="header-anchor" href="#结合-printf-和-scanf" aria-label="Permalink to &quot;结合 printf 和 scanf&quot;">​</a></h4><p>您可以轻松构建交互式控制台工具：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    char name[50];</span></span>
<span class="line"><span>    int year;</span></span>
<span class="line"><span>    printf(&quot;Enter your name: &quot;);</span></span>
<span class="line"><span>    scanf(&quot;%49s&quot;, name); // limit input to 49 chars + null</span></span>
<span class="line"><span>    printf(&quot;Enter your birth year: &quot;);</span></span>
<span class="line"><span>    scanf(&quot;%d&quot;, &amp;year);</span></span>
<span class="line"><span>    printf(&quot;Hi %s! You are about %d years old.\\n&quot;, name, 2025 - year);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Enter your name: Alice</span></span>
<span class="line"><span>Enter your birth year: 2000</span></span>
<span class="line"><span>Hi Alice! You are about 25 years old.</span></span></code></pre></div><h4 id="格式化输出到文件和字符串" tabindex="-1">格式化输出到文件和字符串 <a class="header-anchor" href="#格式化输出到文件和字符串" aria-label="Permalink to &quot;格式化输出到文件和字符串&quot;">​</a></h4><p>您可以在任何地方重定向格式化输出，而不仅仅是屏幕。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fprintf(stderr, &quot;Error: invalid input.\\n&quot;); // print to stderr</span></span>
<span class="line"><span>char buffer[50];</span></span>
<span class="line"><span>sprintf(buffer, &quot;Pi = %.3f&quot;, 3.14159); // print to string</span></span>
<span class="line"><span>puts(buffer);</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Pi = 3.142</span></span></code></pre></div><h4 id="为什么它很重要" tabindex="-1">为什么它很重要 <a class="header-anchor" href="#为什么它很重要" aria-label="Permalink to &quot;为什么它很重要&quot;">​</a></h4><p><code>printf()</code>和<code>scanf()</code>是控制台 I/O 的主力。他们教你：</p><ul><li>数据如何在内存和流之间移动。</li><li>如何控制数字精度和布局。</li><li>输入和输出如何与终端或文件交互。</li></ul><p>每个 C 系统，从微型微控制器到完整的操作系统，都使用这些相同的基础。</p><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><ol><li>打印一个包含两列的数字表：数字及其平方。</li><li>使用读取三个整数<code>scanf</code>并打印他们的平均值。</li><li>使用<code>fgets</code>和<code>sscanf</code>安全地解析<code>&quot;42 3.14&quot;</code>分为 int 和 float。</li><li>编写一个小测验应用程序：提出问题、读取输入、打印“正确”或“重试”。</li><li>尝试打印<code>stderr</code>，将错误重定向到文件。</li></ol><p>掌握标准 I/O 就像掌握程序的声音一样，这就是 C 代码说话和倾听的方式。接下来，您将更深入地了解文件处理，在第 42 节中学习如何使用文件指针打开、读取和写入文件。</p>`,46)])])}const f=s(p,[["render",i]]);export{h as __pageData,f as default};
